187	112      static Object find(String s, Applicable defn, String declarer) {
188	113          int dot = s.lastIndexOf('.');
189	114          String cls = s.substring(0, dot), name = s.substring(dot + 1);
190	115          Class<?> c;
191	116          try { c = Class.forName(cls); }
192	117          catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
193	118          List<Method> named = new ArrayList<Method>();
194	119          for (Method x : c.getMethods())
195	120              if (x.getName().equals(name) && Modifier.isStatic(x.getModifiers())) named.add(x);
196	121          if (named.isEmpty()) return "Native helper " + s + " names no static method of " + cls + ".";
197	122          List<Class<?>> want = new ArrayList<Class<?>>();
198	123          boolean hasSelf = false;
199	124          for (Param p : NodeUtil.getParams(defn)) {
200	125              String pn = p.getName().getText();
201	126              if (pn.equals("self")) { hasSelf = true; continue; }
202	127              Class<?> j = javaFor(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null);
203	128              if (j == null || j == void.class)
204	129                  return "Native helper " + s + ": no Java type carries the declared type of parameter " + pn + ".";
205	130              want.add(j);
206	131          }
207	132          Class<?> res = null;    // a declaration without a result type is refused by NativeApp.init
208	133          if (hasResultType(defn)) {
209	134              res = javaFor(declaredResult(defn));
210	135              if (res == null) return "Native helper " + s + ": no Java type carries the declared result type.";
211	136          }
212	137          Class<?> selfJava = null;
213	138          if (declarer != null) {
214	139              selfJava = javaForSelf(declarer);
215	140              if (selfJava == null)
216	141                  return "Native helper " + s + ": no Java type carries " + declarer + ", the type of self.";
217	142          }
218	143          List<Method> fits = new ArrayList<Method>();
219	144          for (Method x : named) {
220	145              Class<?>[] xs = x.getParameterTypes();
221	146              int off = xs.length - want.size();          // 1: self first
222	147              if (off < 0 || off > 1 || ((hasSelf || selfJava != null) && off != 1)) continue;
223	148              boolean ok = (res == null || x.getReturnType() == res)
224	149                           && (x.getReturnType() == void.class || carried(x.getReturnType()));
225	150              for (int i = 0; ok && i < xs.length; i++) {
226	151                  if (!carried(xs[i])) ok = false;
227	152                  else if (i >= off && xs[i] != want.get(i - off)) ok = false;
228	153              }
229	154              if (ok && selfJava != null && xs[0] != selfJava) ok = false;
230	155              if (ok) fits.add(x);
231	156          }
232	157          if (fits.size() == 1) return fits.get(0);
233	158          if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
234	159          return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
235	160      }
