    53	    private static String fortressTypeName(String s) {
    54	        if (s.equals(Naming.SNOWMAN)) return "()";
    55	        int left = s.indexOf(Naming.LEFT_OXFORD_CHAR);
    56	        String stem = left == -1 ? s : s.substring(0, left);
    57	        String name = stem.substring(Math.max(stem.lastIndexOf('/'), stem.lastIndexOf('$')) + 1);
    58	        if (stem.startsWith(Naming.RT_VALUES_PKG)) name = name.substring(1); // FZZ32 is ZZ32
    59	        if (left == -1) return name;
    60	        List<String> args = RTHelpers.extractStringParameters(s);
    61	        boolean arrow = stem.equals(Naming.ARROW_TAG) || stem.equals(Naming.ABSTRACT_ARROW);
    62	        int last = arrow ? args.size() - 1 : args.size();
    63	        StringBuilder sb = new StringBuilder();
    64	        for (int i = 0; i < last; i++)
    65	            sb.append(i == 0 ? "" : ",").append(fortressTypeName(args.get(i)));
    66	        String inner = sb.toString();
    67	        if (arrow)
    68	            return (last == 1 ? inner : "(" + inner + ")") + "->" + fortressTypeName(args.get(last));
    69	        if (stem.equals(Naming.TUPLE_TAG) || stem.equals(Naming.CONCRETE_TUPLE))
    70	            return "(" + inner + ")";
    71	        return name + "[\\" + inner + "\\]";
    72	    }
